// This KQL query was generated by AI:
// "Detect any vibration anomalies in the last 30 minutes across all wind turbines, show me the worst offender, and tell me what it's doing to its power output."
//
WindTurbineTelemetry
| where timestamp > ago(30m)
| summarize max_vibration = max(vibration_mm_s) by turbine_id
| top 1 by max_vibration desc
| join kind=inner (
    WindTurbineTelemetry
    | where timestamp > ago(30m)
    | summarize latest_time = max(timestamp) by turbine_id
    | join kind=inner (
        WindTurbineTelemetry
        | where timestamp > ago(30m)
    ) on turbine_id, $left.latest_time == $right.timestamp
    | project turbine_id, latest_power_mw = power_mw, latest_vibration_mm_s = vibration_mm_s, latest_time
) on turbine_id
| project turbine_id, max_vibration, latest_vibration_mm_s, latest_power_mw, latest_time

// This KQL query was generated by AI:
// "Show me the real-time efficiency of every solar inverter — actual power output vs theoretical maximum given current irradiance — and flag any underperforming by more than 10%."
//
SolarInverterTelemetry
| where timestamp > ago(5m)
| summarize latest_time = max(timestamp) by inverter_id
| join kind=inner (
    SolarInverterTelemetry
    | where timestamp > ago(5m)
) on inverter_id, $left.latest_time == $right.timestamp
| extend theoretical_max_kw = irradiance_wm2 * 0.2  // Assume 20% panel efficiency for theoretical max (adjust as needed)
| extend performance_ratio = power_kw / theoretical_max_kw
| extend underperforming = performance_ratio < 0.9
| project inverter_id, timestamp, power_kw, irradiance_wm2, theoretical_max_kw, performance_ratio, underperforming

// This KQL query was generated by AI:
// "Where is every service vessel right now, what's its destination, ETA, and is any vessel currently within 5 nautical miles of a turbine with an open critical maintenance order?"
//
let vessel_latest = VesselPositions
| summarize latest_time=max(timestamp) by vessel_id
| join kind=inner (
    VesselPositions
) on vessel_id, $left.latest_time == $right.timestamp
| project vessel_id, vessel_name, vessel_type, latitude, longitude, destination, eta_hours, timestamp;
let turbines_critical = WindFarmsLive
| where fault_type has "Critical" and isnotempty(fault_type)
| summarize latest_time=max(timestamp) by turbine_id
| join kind=inner (
    WindFarmsLive
    | where fault_type has "Critical" and isnotempty(fault_type)
) on turbine_id, $left.latest_time == $right.timestamp
| project turbine_id, latitude, longitude, fault_type, timestamp;
vessel_latest
| extend is_service_vessel = vessel_type has "Service"
| join kind=leftouter (
    turbines_critical
    | extend turbine_lat=latitude, turbine_lon=longitude
) on 1==1
| where is_service_vessel
| extend distance_nm = 60 * geo_distance_2points(latitude, longitude, turbine_lat, turbine_lon) / 1852.0
| summarize vessels_within_5nm = countif(distance_nm <= 5) > 0 by vessel_id
| join kind=inner (
    vessel_latest
    | extend is_service_vessel = vessel_type has "Service"
) on vessel_id
| project vessel_id, vessel_name, latitude, longitude, destination, eta_hours, timestamp, vessels_within_5nm

