// This KQL query was generated by AI:
// "What's our live carbon intensity in gCO₂ per kWh right now across the whole portfolio — and how much higher would it be if WT-NAX-04 stayed offline for the next hour and the gas plant in Thrace had to compensate?"
//
let now_ts = toscalar(EmissionsStream | summarize max_ts = max(timestamp));
let wind_power = toscalar(WindTurbineTelemetry | where timestamp == now_ts | summarize wind_sum = sum(power_mw));
let solar_power = toscalar(SolarInverterTelemetry | where timestamp == now_ts | summarize solar_sum = sum(power_kw) / 1000.0);
let gas_power = toscalar(EmissionsStream | where timestamp == now_ts and fuel_type has "Gas" | summarize gas_sum = sum(power_output_mw));
let total_power_mw = wind_power + solar_power + gas_power;
let total_co2_kg = toscalar(EmissionsStream | where timestamp == now_ts | summarize co2_sum = sum(co2_kg_per_hour) / 3600.0);
let carbon_intensity_live = iff(total_power_mw > 0, (total_co2_kg * 1000.0) / (total_power_mw), real(null));
let wt_nax_04_power = toscalar(WindTurbineTelemetry | where timestamp == now_ts and turbine_id == "WT-NAX-04" | summarize nax04_sum = sum(power_mw));
let compensated_gas_plant = EmissionsStream
    | where timestamp == now_ts and plant_name has "Thrace" and fuel_type has "Gas"
    | summarize plant_id = any(plant_id), co2_kg_per_hour = max(co2_kg_per_hour), power_output_mw = max(power_output_mw);
let new_gas_power = compensated_gas_plant.power_output_mw + wt_nax_04_power;
let new_gas_co2_kg_per_hour = compensated_gas_plant.co2_kg_per_hour * (new_gas_power / compensated_gas_plant.power_output_mw);
let new_total_power_mw = total_power_mw;
let new_total_co2_kg = (total_co2_kg * 3600.0 - compensated_gas_plant.co2_kg_per_hour + new_gas_co2_kg_per_hour) / 3600.0;
let carbon_intensity_sim = iff(new_total_power_mw > 0, (new_total_co2_kg * 1000.0) / (new_total_power_mw), real(null));
print carbon_intensity_live_gCO2_per_kWh = carbon_intensity_live, carbon_intensity_if_WT_NAX_04_offline_gCO2_per_kWh = carbon_intensity_sim, increase_gCO2_per_kWh = carbon_intensity_sim - carbon_intensity_live

