// This KQL query was generated by AI:
// "Show me live emissions per plant ordered by intensity."
//
EmissionsStream
| summarize latest_time = max(timestamp) by plant_id
| join kind=inner (
    EmissionsStream
) on plant_id
| where timestamp == latest_time
| extend carbon_intensity_gCO2_per_kWh = iff(power_output_mw > 0, (co2_kg_per_hour * 1000.0) / (power_output_mw * 1000.0), real(null))
| project plant_id, plant_name, timestamp, power_output_mw, co2_kg_per_hour, carbon_intensity_gCO2_per_kWh
| order by carbon_intensity_gCO2_per_kWh desc

